import urllib.request, re
urls=[
 'https://raw.githubusercontent.com/cran/bloodTyper/master/README.md',
 'https://raw.githubusercontent.com/cran/bloodTyper/master/R/bloodTyper.R',
]
for url in urls:
 print('URL',url)
 try:
  text=urllib.request.urlopen(url, timeout=20).read().decode('utf-8','ignore')
  for term in ['rs8176749','rs8176743','rs8176719','rs2519093','rs8176715']:
   m=re.search(term+'.{0,120}', text)
   if m: print(m.group(0)[:300])
 except Exception as e: print('ERR',e)
PY"

