import urllib.request, re
base='https://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/1000_genomes_project/release/'
try:
 text=urllib.request.urlopen(base,timeout=20).read().decode('utf-8','ignore')
 for href in re.findall(r'href=\"(["'^"]+)"'"', text): print(href)
except Exception as e: print(e)
PY"

